\documentclass[11pt]{article}
\usepackage[margin=2.5cm]{geometry}

\title{Riparian Buffer Structure Along Kaspian Creek}
\author{K.~Aldana and M.~Ostrander}
\date{August 2026}

\begin{document}
\maketitle

\begin{abstract}
We report a two-season survey of the riparian corridor above the
Kaspian Creek gauging station, with emphasis on canopy closure,
basal area, and the survival of the 2019 planting cells.
\end{abstract}

\input{chapters/fieldwork}
\input{chapters/analysis}

\section{Conclusions}
\label{sec:conclusions}

The corridor recovers fastest where the survey grid of
Figure~\ref{fig:creek} overlaps the 2019 planting cells, and the
narrow reaches argue for extending the buffer upslope.

\end{document}

\section{Field Layout}
\label{sec:field}

Three 50~m transects were run perpendicular to the channel at
each of the twelve sampling reaches. Canopy closure was recorded
with a spherical densiometer at 10~m intervals, and every stem
over 5~cm DBH was tallied by species.

\begin{figure}[htbp]
\centering
\fbox{\rule{0pt}{4cm}\rule{6cm}{0pt}}
\caption{Layout of transects and planting cells along Kaspian
Creek, keyed to the reach numbers used in the field books.}
\label{fig:creek}
\end{figure}

Basal area was estimated with a 10-factor prism at every second
densiometer station. Sediment pins were installed at the toe of
each bank and read after both high-flow events.

